def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return float(min(budget, 18.0))

    prev_bids = []
    eric_bid = None
    cindy_bid = None
    urgent_opponents = 0

    for opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
        if opp.get('no_water_days', 0) >= 2 or opp.get('hp', 10) <= 3:
            urgent_opponents += 1

    if 'Eric' in opponents_status and opponents_status['Eric'].get('alive'):
        prev = (opponents_status['Eric'].get('previous_trace', {}) or {})
        if prev.get('bid') is not None:
            eric_bid = float(prev.get('bid'))

    if 'Cindy' in opponents_status and opponents_status['Cindy'].get('alive'):
        prev = (opponents_status['Cindy'].get('previous_trace', {}) or {})
        if prev.get('bid') is not None:
            cindy_bid = float(prev.get('bid'))

    low_supply = supply <= 17
    high_supply = supply >= 22
    danger = no_water_days >= 2 or hp <= 4
    moderate = no_water_days >= 1 or hp <= 6

    target = 24.0

    if eric_bid is not None:
        target = max(target, eric_bid + 2.0)
    elif prev_bids:
        target = max(target, max(prev_bids) * 0.78 + 1.0)

    if cindy_bid is not None and cindy_bid >= 120:
        target = min(target, 72.0)

    if high_supply and not danger:
        target *= 0.72
    elif low_supply:
        target *= 1.22

    if urgent_opponents >= 2:
        target *= 1.12

    if moderate:
        target = max(target, 46.0)
    if danger:
        target = max(target, 68.0)

    days_left = max(1, 10 - day + 1)
    reserve_floor = days_left * 12.0
    affordable = max(0.0, budget - reserve_floor)

    if danger:
        cap = min(budget, max(affordable + 20.0, DAILY_SALARY * 1.05))
    else:
        cap = min(budget, max(affordable, 22.0))

    bid = min(target, cap)

    if bid < 0:
        bid = 0.0

    if not danger and high_supply and budget < 120:
        bid = min(bid, 18.0)

    return float(max(0.0, min(budget, round(bid, 2))))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = int(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive'):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace only
    yesterday_bids = []
    yesterday_hp_after = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass
        hp_after = prev.get('hp_after', None)
        if hp_after is not None:
            try:
                yesterday_hp_after.append(float(hp_after))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    lowest_prev_bid = min(yesterday_bids) if yesterday_bids else 0.0

    # Base urgency: if I have low HP or have already gone without water, bid higher.
    urgency = 0.0
    if my_hp <= 2:
        urgency += 0.8
    elif my_hp <= 4:
        urgency += 0.5
    else:
        urgency += 0.25

    if my_no_water_days >= 2:
        urgency += 0.5
    elif my_no_water_days == 1:
        urgency += 0.25

    # If someone was bidding extremely high yesterday, they likely secured water.
    # I should avoid matching extremes but still bid enough to compete.
    # Use a cap to protect budget.
    extreme_threshold = DAILY_SALARY * 1.6  # 144

    # Supply factor: higher supply reduces need to overbid.
    supply_factor = 0.9
    if supply >= 22.0:
        supply_factor = 0.85
    elif supply <= 17.0:
        supply_factor = 1.05

    # Determine target bid level.
    if highest_prev_bid >= extreme_threshold:
        # Cindy-like behavior: overbidding; we undercut.
        target = max(DAILY_SALARY * 0.45, highest_prev_bid * 0.55)
    else:
        # Otherwise, bid around median-ish level inferred from highest.
        target = max(DAILY_SALARY * 0.5, highest_prev_bid * 0.7)

    # Apply urgency and supply adjustment.
    target = target * supply_factor * (1.0 + 0.6 * urgency)

    # Budget safety: never bid more than budget.
    # Also avoid wasting money when already reasonably healthy.
    if my_hp >= 7 and my_no_water_days == 0:
        target *= 0.85

    max_affordable = my_budget
    bid = min(max_affordable, target)

    # Keep non-negative and add a tiny day-based jitter to avoid ties.
    if bid < 0.0:
        bid = 0.0
    bid += (day % 3) * 0.1

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    current_bid = DAILY_SALARY * 0.5

    # Adjust based on my HP
    if my_status['hp'] <= 2:
        current_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 5:
        current_bid = DAILY_SALARY * 0.75
    elif my_status['hp'] >= 9:
        current_bid = DAILY_SALARY * 0.4

    # Adjust based on opponent's highest previous bid
    if highest_prev_bid > 0:
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_status['hp'] <= 3:
                current_bid = max(current_bid, highest_prev_bid + 5)
            else:
                current_bid = max(current_bid, highest_prev_bid * 0.9)
        elif highest_prev_bid >= DAILY_SALARY * 0.5:
            current_bid = max(current_bid, highest_prev_bid + 2)
        else:
            current_bid = max(current_bid, highest_prev_bid * 1.1)

    # Adjust based on supply scarcity
    total_water_needed = WATER_REQ
    for opp in alive_opponents:
        total_water_needed += opp['water_requirement']

    if day_context['supply'] < total_water_needed / 2:
        current_bid *= 1.2
    elif day_context['supply'] < total_water_needed:
        current_bid *= 1.1
    elif day_context['supply'] >= total_water_needed * 1.5:
        current_bid *= 0.8
    elif day_context['supply'] >= total_water_needed:
        current_bid *= 0.9

    # Adjust based on day progression
    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2:
        if my_status['hp'] <= 5:
            current_bid = max(current_bid, DAILY_SALARY * 0.95)
        else:
            current_bid = max(current_bid, DAILY_SALARY * 0.8)
    elif day_context['day'] <= 3:
        if my_status['hp'] > 5:
            current_bid = min(current_bid, DAILY_SALARY * 0.6)

    final_bid = max(1.0, current_bid)
    final_bid = min(final_bid, my_status['budget'])

    if my_status['hp'] <= 2:
        final_bid = min(final_bid, my_status['budget'])
    else:
        final_bid = min(final_bid, DAILY_SALARY * 1.2)

    return final_bid
